kIn = input(7, "K Neighbors", 1, 15, 1)
featWin = input(20, "Feature Window", 5, 40, 1)
libLen = input(200, "Library Lookback", 50, 400, 10)
margTh = input(0.43, "Margin Threshold", 0.1, 0.9, 0.01)
disTh = input(0.45, "Disagreement Threshold", 0.1, 0.9, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

var r1Hist = array(0)
var r2Hist = array(0)
var cHist = array(0)

// ─── Per-bar raw features (bar-data modulated) ───
cPrev = close[1]
r1 = 0.0
if cPrev != 0.0 { r1 := (close - cPrev) / cPrev }
r2 = 0.0
if open != 0.0 { r2 := (close - open) / open }

array.push(r1Hist, r1)
array.push(r2Hist, r2)
array.push(cHist, close)

n = array.size(cHist)

// ─── Z-score baselines over LibraryLookback (mean-dev, Wilder-style audit) ───
mean1 = 0.0
mean2 = 0.0
cnt = 0
if n > 1 {
    s = n - libLen
    if s < 0 { s := 0 }
    j = s
    while j < n {
        mean1 := mean1 + r1Hist[j]
        mean2 := mean2 + r2Hist[j]
        cnt := cnt + 1
        j := j + 1
    }
}
if cnt > 0 {
    mean1 := mean1 / cnt
    mean2 := mean2 / cnt
}
sd1 = 0.0
sd2 = 0.0
if cnt > 1 {
    s2 = n - libLen
    if s2 < 0 { s2 := 0 }
    j = s2
    while j < n {
        d1 = r1Hist[j] - mean1
        d2 = r2Hist[j] - mean2
        sd1 := sd1 + d1 * d1
        sd2 := sd2 + d2 * d2
        j := j + 1
    }
    sd1 := sqrt(sd1 / cnt)
    sd2 := sqrt(sd2 / cnt)
}
if sd1 < 0.0000001 { sd1 := 0.0000001 }
if sd2 < 0.0000001 { sd2 := 0.0000001 }

// ─── KNN 7x20 vote ───
upVotes = 0
downVotes = 0
marginVal = r1 * 8.0
disagreeVal = 0.5 + r2 * 8.0
if disagreeVal < 0.0 { disagreeVal := 0.0 }
if disagreeVal > 1.0 { disagreeVal := 1.0 }

ready = n >= featWin + 2 and n >= 30
if ready {
    // top-k holders
    bestD = array(0)
    bestL = array(0)
    m = 0
    while m < kIn {
        array.push(bestD, 999999.0)
        array.push(bestL, 0)
        m := m + 1
    }
    // candidate range: needs full 20-window + a next-bar label
    cStart = n - 1 - libLen
    if cStart < featWin { cStart := featWin }
    cEnd = n - 2
    j = cStart
    while j <= cEnd {
        dist = 0.0
        t = 0
        while t < featWin {
            a1 = (r1Hist[n - 1 - t] - r1Hist[j - t]) / sd1
            a2 = (r2Hist[n - 1 - t] - r2Hist[j - t]) / sd2
            dist := dist + a1 * a1 + a2 * a2
            t := t + 1
        }
        dist := sqrt(dist)
        // label of historical bar j from realized next bar
        lab = 0 - 1
        if cHist[j + 1] > cHist[j] { lab := 1 }
        // insertion into sorted top-k
        ins = 0 - 1
        m = 0
        while m < kIn {
            if dist < bestD[m] {
                ins := m
                m := kIn
            }
            m := m + 1
        }
        if ins >= 0 {
            m = kIn - 1
            while m > ins {
                array.set(bestD, m, bestD[m - 1])
                array.set(bestL, m, bestL[m - 1])
                m := m - 1
            }
            array.set(bestD, ins, dist)
            array.set(bestL, ins, lab)
        }
        j := j + 1
    }
    up = 0
    dn = 0
    m = 0
    while m < kIn {
        if bestD[m] < 999998.0 {
            if bestL[m] == 1 { up := up + 1 }
            else { dn := dn + 1 }
        }
        m := m + 1
    }
    upVotes := up
    downVotes := dn
    tot = up + dn
    if tot > 0 {
        mm = (up - dn) / tot
        marginVal := mm
        dd = 1.0 - abs(mm)
        disagreeVal := dd
    }
}

// ─── Signal rules: both channels must agree ───
bullState = marginVal > margTh and disagreeVal < disTh
bearState = marginVal < 0 - margTh and disagreeVal < disTh
buySig = bullState and not bullState[1]
sellSig = bearState and not bearState[1]

// ─── 2D signal markers (events on edges) ───
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
// ─── 3D cones in SAME pane as 3D geometry ───
if buySig {
    plotshape_3d(bar_index, marginVal, "Buy", "coneup", "#22cc88", markerSize, 0, "separate")
}
if sellSig {
    plotshape_3d(bar_index, marginVal, "Sell", "conedown", "#ff4477", markerSize, 1, "separate")
}

// ─── 2D channels: independently readable ───
plot(marginVal, "Vote Margin", "#22cc88", 2, "separate")
plot(disagreeVal, "Disagreement", "#b48cff", 2, "separate")
hline(0, "#888888", "separate")

// ─── 3D form: height = margin, sheath = disagreement ───
// bars3d columns: tall pillars when crisp, short stubs when contested
plot3d(marginVal, "Margin Columns", "bars3d", "#22cc88", "separate")
// surface sheath: disagreement terrain at distinct depth
plot3d(disagreeVal, "Disagreement Sheath", "surface", "#b48cff", "separate", 1)

// Visible Session Volume Value Terrain
// Volume-profile-at-price engine: POC + value area from session bins.

rows = input(24, "Profile Rows", 10, 48, 1)
vaPct = input(70, "Value Area %", 50, 90, 5)
sessLen = input(120, "Session Length", 20, 300, 5)
extendRight = input(true, "Extend POC/VAH/VAL Right")
enable3D = input(true, "Enable 3D Terrain")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
if rng < 0.0000001 {
    rng := 0.0000001
}

binVol = array()
b = 0
while b < rows {
    array.push(binVol, 0.0)
    b := b + 1
}

k = 0
while k < sessLen {
    tkHigh = high[k]
    tkLow = low[k]
    tkClose = close[k]
    tkVol = volume[k]
    typ = (tkHigh + tkLow + tkClose) / 3
    bi = floor((typ - ll) / rng * rows)
    if bi < 0 {
        bi := 0
    }
    if bi > rows - 1 {
        bi := rows - 1
    }
    if tkHigh == tkLow {
        bi := floor(rows / 2)
        if bi < 0 {
            bi := 0
        }
        if bi > rows - 1 {
            bi := rows - 1
        }
    }
    cur = array.get(binVol, bi)
    array.set(binVol, bi, cur + tkVol)
    k := k + 1
}

totalVol = array.sum(binVol)

pocBin = 0
pocVal = array.get(binVol, 0)
j = 1
while j < rows {
    v = array.get(binVol, j)
    if v > pocVal {
        pocVal := v
        pocBin := j
    }
    j := j + 1
}
pocPrice = ll + (pocBin + 0.5) / rows * rng
pocShare = 0.0
if totalVol > 0 {
    pocShare := pocVal / totalVol * 100
}

vaLow = pocBin
vaHigh = pocBin
accum = pocVal
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < rows {
    leftVal = 0 - 1.0
    if vaLow > 0 {
        leftVal := array.get(binVol, vaLow - 1)
    }
    rightVal = 0 - 1.0
    if vaHigh < rows - 1 {
        rightVal := array.get(binVol, vaHigh + 1)
    }
    if rightVal >= leftVal and vaHigh < rows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        } else {
            if vaHigh < rows - 1 {
                vaHigh := vaHigh + 1
                accum := accum + rightVal
            }
        }
    }
    guard := guard + 1
}
vahPrice = ll + (vaHigh + 1) / rows * rng
valPrice = ll + vaLow / rows * rng
vaShare = 0.0
if totalVol > 0 {
    vaShare := accum / totalVol * 100
}
terrainH = pocShare + vaShare * 0.05 + (close - ll) / rng * 2

insideVA = close >= valPrice and close <= vahPrice
prevInside = insideVA[1]
prevVah = vahPrice[1]
prevVal = valPrice[1]
buySig = prevInside and close > vahPrice and close[1] <= prevVah
sellSig = prevInside and close < valPrice and close[1] >= prevVal

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "3d")
}
if pocBin != pocBin[1] {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 1, "3d")
}

plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(pocShare, "POC Share", "#ffd43b", 1, "separate")
plot(vaShare, "VA Share", "#4488ff", 1, "separate")

plot3d(terrainH, "Value Terrain", "surface", "#4488ff", "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vahPrice, "VAH Line", "line3d", "#22cc88", "3d", 2)

// FIX 1: var lvl = highest(high, 20) froze at bar 0 -> plain assignment recomputed every bar.
// FIX 2: close[-1] is a future leak -> use close > lvl for a confirmed breakout.
// FIX 3: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine syntax -> bare style string + hex color + bar_index.
// FIX 4: oscillator RSI in pane="3d" renders as spiky forest over price -> moved to pane="separate".
// FIX 5: 3D cones/labels must pair with a plot3d in the EXACT SAME pane -> added matching separate-pane cones + 2D twins.
hiLen = input(20, "High Length", 1, 100, 1)
rsiLen = input(14, "RSI Length", 2, 50, 1)
osLevel = input(30, "Oversold Level", 1, 50, 1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

lvl = highest(high, hiLen)
r = rsi(close, rsiLen)

buySig = close > lvl
osSig = crossover(r, osLevel)

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}

if buySig {
    plotshape_3d(bar_index, lvl, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate")
}
if osSig {
    plotshape_3d(bar_index, r, "OS", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate")
}

plot(r, "RSI", "#b48cff", 1, "line")
hline(osLevel, "#22cc88")
plot(lvl, "High Level", "#ffcc44", 1, "stepline")
plot3d(r, "RSI", "surface", "#b48cff", "separate")

flowSrc = input(close, "Flow PSI Source")
critThresh = input(150, "Critical Threshold", 50, 300, 1)
spinFactor = input(0.5, "Spin Factor", 0.05, 2.0, 0.05)
ringCount = input(5, "Ring Count", 1, 5, 1)
ringRate = input(2.0, "Ring Expansion Rate", 0.2, 10.0, 0.2)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

flowVal = flowSrc
spinSpeed = flowVal * spinFactor
overState = flowVal > critThresh
discPerim = 2.0
maxRadius = 12.0

var discAngle = 0.0
var r1 = 0.0
var r2 = 0.0
var r3 = 0.0
var r4 = 0.0
var r5 = 0.0

if overState {
  discAngle := discAngle[1]
} else {
  discAngle := discAngle[1] + spinSpeed
}
if discAngle > 360 {
  discAngle := discAngle - 360
}

if overState {
  r1 := r1[1] + ringRate
  r2 := r2[1] + ringRate
  r3 := r3[1] + ringRate
  r4 := r4[1] + ringRate
  r5 := r5[1] + ringRate
} else {
  r1 := 0.0
  r2 := 0.0
  r3 := 0.0
  r4 := 0.0
  r5 := 0.0
}
if r1 > maxRadius {
  r1 := discPerim
}
if r2 > maxRadius {
  r2 := discPerim
}
if r3 > maxRadius {
  r3 := discPerim
}
if r4 > maxRadius {
  r4 := discPerim
}
if r5 > maxRadius {
  r5 := discPerim
}
ringAvg = (r1 + r2 + r3 + r4 + r5) / 5
activeRings = (r1 + r2 + r3 + r4 + r5) / ringCount
spinWrapped = discAngle * flowVal / 360

alertStart = overState and not overState[1]
alertEnd = not overState and overState[1]

if alertStart {
  plotshape(bar_index, low, "OVERPRESSURE", "triangleup", "#ff4477")
  plotshape_3d(bar_index, low, "Lock", "cube", "#ff4477", 1.0 * markerSize, 0, "separate", 0, discAngle, 0)
  label3d(bar_index, high, "OVERPRESSURE", "#ff4477", 1, 2, "separate")
}
if alertEnd {
  plotshape(bar_index, high, "Pressure Normal", "triangledown", "#22cc88")
  plotshape_3d(bar_index, high, "Unlock", "diamond", "#22cc88", 1.0 * markerSize, 0, "separate")
}

plot(flowVal, "Flow PSI", "#33aaff", 2, "separate")
plot(spinSpeed, "Spin Speed", "#ffaa22", 1, "separate")
hline(critThresh, "#ff4477", "separate")
plot3d(flowVal, "Flow PSI", "ribbon", "#33aaff", "separate", 0)
plot3d(spinSpeed, "Spin Speed", "trail", "#ffaa22", "separate", 1)
plot3d(activeRings, "Shockwave Rings", "torus", "#ff4477", "separate", 2)
